import{_ as t,o as i,c as s,a2 as e}from"./chunks/framework.DdtnLau3.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Piwork","text":"可分享、可运行的 AI 工作空间","tagline":"由可演进的 Harness 驱动。","image":{"src":"/logo.png","alt":"Piwork"},"actions":[{"theme":"brand","text":"开始使用","link":"/zh/guide/installation"},{"theme":"alt","text":"GitHub","link":"https://github.com/pphboy/piwork"},{"theme":"alt","text":"讨论社区","link":"https://github.com/pphboy/piwork/discussions"}]}},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md"}'),r={name:"zh/index.md"};function n(o,a,h,k,p,l){return i(),s("div",null,[...a[0]||(a[0]=[e(`<h2 id="piwork-是什么" tabindex="-1">Piwork 是什么？ <a class="header-anchor" href="#piwork-是什么" aria-label="Permalink to &quot;Piwork 是什么？&quot;">​</a></h2><p>Piwork 将可运行的 AI 工作空间封装成一个可携带的单元，称为 <strong>Work</strong>。应用、文件、对话历史和执行环境保存在一起；导出后，可以在另一个 Piwork 实例中继续使用。</p><table tabindex="0"><thead><tr><th>概念</th><th>职责</th></tr></thead><tbody><tr><td><a href="/piwork/zh/concepts/work.html">Work</a></td><td><strong>工作空间。</strong> 保存环境和持久状态。</td></tr><tr><td><a href="/piwork/zh/concepts/service.html">Service</a></td><td><strong>能力。</strong> 运行应用、API 或其他容器服务。</td></tr><tr><td><a href="/piwork/zh/concepts/harness.html">Harness</a></td><td><strong>智能层。</strong> 通过模型、工具和工作空间专属指令理解并操作 Work。</td></tr></tbody></table><p>Harness 可以帮助构建和修改它所在的工作空间。它的指令、Skills、扩展包和经过验证的经验，可以随着 Work 一起演进。</p><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><p><strong>创建 → 运行 → 演进 → 导出 → 分享 → 导入 → 继续</strong></p><p>将已停止的 Work 导出为 <code>.work</code> 文件，在兼容的实例中导入，再手动启动。接收方需要配置自己的模型凭据。</p><h2 id="演示-kanban-work" tabindex="-1">演示：Kanban Work <a class="header-anchor" href="#演示-kanban-work" aria-label="Permalink to &quot;演示：Kanban Work&quot;">​</a></h2><p>看板、数据、应用 Service 和帮助构建及操作看板的 Harness，共同组成一个工作空间。<a href="/piwork/zh/demo/kanban.html">查看 Kanban 演示说明</a>。可下载的演示包和录屏仍在准备中。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>如果你能运行 Docker，就可以尝试 Piwork。你需要 Linux x86-64 Core 主机、Docker Engine 28+、Compose 2.24+ 和模型服务账号。客户端支持 Linux 和 Windows Docker Desktop。</p><p><a href="/piwork/zh/guide/installation.html">下载并配置 Docker 安装文件</a>，然后启动 Core：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.core.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core</span></span></code></pre></div><p><a href="/piwork/zh/guide/quick-start.html">打开 Desktop，运行第一个 Work</a>。问题和反馈可以提交到 <a href="https://github.com/pphboy/piwork/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>。</p>`,14)])])}const g=t(r,[["render",n]]);export{c as __pageData,g as default};
